import time
from .base import EMSSInterface
from ..utilities.AlarmConverter import AlarmConverter
import six


class AlarmManager(EMSSInterface):
    """
    EMSsim keywords related to alarms
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'  # 'TEST CASE' 'GLOBAL'

    def __init__(self):
        super(AlarmManager, self).__init__()

    def get_enb_active_alarms(self, retry_limit=3, retry_sleep=20, enb_id=None, bts_id=None, alias=None):
        """
        Refreshes eNB alarms and returns active alarms.

        This method also clears alarms history.

        :param retry_limit: number of retries if alarm_status failed (default=3)
        :param retry_sleep: sleep between retries (default=20)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :return: array of dictionaries of type:
            [{'#': '1', 'OBJECT': '/bts-35', 'SEVERITY': 'MAJOR',
            'TEXT': 'BTS reference clock missing', 'ACTIVITY': 'SET',
            'TIME': '14-07-16 07:54:06', 'ID': '30289', 'HEXID': '7651'}]

        +----------------+-----------------------+
        |                Examples                |
        +================+=======================+
        | @{alarm_list}= | get enb active alarms |
        +----------------+-----------------------+
        """
        retry_limit = self._opt_int(retry_limit)
        retry_sleep = self._opt_int(retry_sleep)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.enb_configuration_should_be_discovered()
        self.refresh_alarm_list(retry_limit, retry_sleep)
        return self.get_alarm_history()

    def get_enb_active_alarms_as_string_of_ids(self, criteria="ID", enb_id=None, bts_id=None, alias=None):
        """
        Refreshes eNB alarms and returns active alarms.

        This method clears also alarm history.

        :param criteria: type of alarm's identifier (default 'ID'). Can be: ID HEXID
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :return: string - comma separated list of alarm IDs of type:
            '30289,30290' (ID) or '7651,7652' (HEXID)

        +----------------+----------------------------------------+-------+
        |                             Examples                            |
        +================+========================================+=======+
        | ${alarm_list}= | get_enb_active_alarms_as_string_of_ids |       |
        +----------------+----------------------------------------+-------+
        | ${alarm_list}= | get_enb_active_alarms_as_string_of_ids | HEXID |
        +----------------+----------------------------------------+-------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        active_alarms = self.get_enb_active_alarms()
        AC = AlarmConverter(active_alarms)
        return ",".join(AC._get_list_of_alarm_details_by_key(criteria))

    def get_alarm_history(self, enb_id=None, bts_id=None, alias=None):
        """
        Returns all alarms saved in EMSsim memory.

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :return: array of dictionaries of type:
            [{'#': '1', 'OBJECT': '/bts-35', 'SEVERITY': 'MAJOR',
            'TEXT': 'BTS reference clock missing', 'ACTIVITY': 'SET',
            'TIME': '14-07-16 07:54:06', 'ID': '30289', 'HEXID': '7651'}]

        +----------------+-------------------+
        |              Examples              |
        +================+===================+
        | @{alarm_list}= | get_alarm_history |
        +----------------+-------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        alarm_command = self._get_emssim().cmd_alarm()
        self._assert(alarm_command.run(), "Checking alarm list operation failed")
        AC = AlarmConverter(alarm_command.returned_data()['alarm_table'])
        return AC.alarm_list

    def should_occur_alarms(self, required_alarms, criteria='ID', enb_id=None, bts_id=None, alias=None):
        """
        Verifies if required alarms exist on eNB.

        This method also clears alarm history.

        :param required_alarms: alarms, which should be active. Can be:
            list - python friendly format
            comma/space separated string - robot friendly format
        :param criteria: type of alarm's identifier (default 'ID'). Can be: ID or HEXID.
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +---------------------+--------------+----------------+
        |                      Examples                       |
        +=====================+==============+================+
        | should occur alarms | 30294 30295  |                |
        +---------------------+--------------+----------------+
        | should occur alarms | 7656,7657    | criteria=HEXID |
        +---------------------+--------------+----------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        required_alarms = self._parse_alarms_provided_by_user(required_alarms)

        AC = AlarmConverter(self.get_enb_active_alarms())
        for required_alarm in required_alarms:
            self._assert(AC.has_alarm_occured(required_alarm, criteria), "Alarm %s hasn't occured" % required_alarm)

    def should_be_no_alarm(self, forbidden_alarm, criteria='ID', enb_id=None, bts_id=None, alias=None):
        """
        Verifies if there is no active alarm on eNB of specified ID.

        This method clears also alarm history.

        :param forbidden_alarm: alarms, which should be active. Can be: int or string
        :param criteria: type of alarm's identifier (default 'ID'). Can be: ID or HEXID.
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +--------------------+-------+----------------+
        |                    Examples                 |
        +====================+=======+================+
        | should_be_no_alarm | 30294 |                |
        +--------------------+-------+----------------+
        | should_be_no_alarm | 7656  | criteria=HEXID |
        +--------------------+-------+----------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        AC = AlarmConverter(self.get_enb_active_alarms())
        self._assert(not AC.has_alarm_occured(forbidden_alarm, criteria), "Alarm %s occured but it should not" % forbidden_alarm)

    def should_be_no_alarms(self, enb_id=None, bts_id=None, alias=None):
        """
        Verifies if there is no active alarm on eNB.

        This method also clears alarm history.

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +---------------------+
        |       Examples      |
        +=====================+
        | should be no alarms |
        +---------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        AC = AlarmConverter(self.get_enb_active_alarms())
        self._assert(AC.get_list_of_alarm_ids() == [], "There is at least one alarm on eNB")

    def should_be_no_alarms_except(self, allowed_alarms, criteria='ID', enb_id=None, bts_id=None, alias=None):
        """
        Verifies if there is no alarm active on eNB except allowed.

        This method also clears alarm history.

        :param allowed_alarms: alarms, which can be active. Can be:
            list - python friendly format
            comma/space separated string - robot friendly format
        :param criteria: type of alarm's identifier (default 'ID'). Can be: ID or HEXID.
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +----------------------------+-----------+-------------------+
        |                          Examples                          |
        +============================+===========+===================+
        | should be no alarms except |          30294,30295          |
        +----------------------------+-----------+-------------------+
        | should be no alarms except | 7656 7657 | criteria=HEXID    |
        +----------------------------+-----------+-------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        allowed_alarms = self._parse_alarms_provided_by_user(allowed_alarms)
        AC = AlarmConverter(self.get_enb_active_alarms())
        for occured_alarm in AC._get_list_of_alarm_details_by_key(criteria):
            self._assert(occured_alarm in allowed_alarms, "There is at least one not allowed alarm. %s : %s " % (criteria, occured_alarm))

    def wait_for_alarm(self, timeout=60, alarm_id=None, fail_no_alarm=True, enb_id=None, bts_id=None, alias=None):
        """
        Waits for alarm.

        :param timeout: Maximum waiting time in seconds (default=60)
        :param alarm_id: Alarm ID to wait for (default=None, i.e. wait for any alarm)
        :param fail_no_alarm: Assert failure if no alarm occurred (defult=True)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :return: Alarm object or None if no alarm occurred

        +-------------------------------+
        |       Examples                |
        +===============================+
        | wait_for_alarm  alarm_id=7656 |
        +-------------------------------+
        """
        timeout = self._opt_int(timeout)
        alarm_id = self._opt_int(alarm_id)
        fail_no_alarm = self._opt_bool(fail_no_alarm)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self._get_emssim().subscribe_events(event_type='alarm')
        alarm = None
        start_time = time.time()
        while time.time() - start_time < timeout:
            alarms = self._get_emssim().get_events(event_type='alarm')
            for alm in alarms:
                if alarm_id:
                    if int(alm['-ALM_ID']) == alarm_id:
                        alarm = alm
                        break
                else:
                    alarm = alm
            if alarm:
                print("ALARM: %s" % str(alarm))
                break
            time.sleep(1)
        self._get_emssim().unsubscribe_events(event_type='alarm')
        if fail_no_alarm:
            self._assert(alarm, "No alarm occurred")
        return alarm

    def refresh_alarm_list(self, retry_limit=3, retry_sleep=20, enb_id=None, bts_id=None, alias=None):
        """
        Refreshes active eNB alarms and clears alarm history.

        :param retry_limit: number of retries if alarm_status failed (default=3)
        :param retry_sleep: sleep between retries (default=20)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +--------------------+
        |      Examples      |
        +====================+
        | refresh_alarm_list |
        +--------------------+
        """
        retry_limit = self._opt_int(retry_limit)
        retry_sleep = self._opt_int(retry_sleep)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        alarm_command = self._get_emssim().cmd_alarm_status()
        command_succeeded = alarm_command.run()
        err_msg = "Refreshing alarm list failed"
        retry_count = 0
        while (retry_count < retry_limit) and not command_succeeded:
            retry_count += 1
            print("%s. Retry %d after sleep %d..." % (err_msg, retry_count, retry_sleep))
            time.sleep(retry_sleep)
            command_succeeded = alarm_command.run()
        self._assert(command_succeeded, err_msg)

    def clear_alarm_history(self, enb_id=None, bts_id=None, alias=None):
        """
        Clears alarm history.

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +---------------------+
        |       Examples      |
        +=====================+
        | clear_alarm_history |
        +---------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        alarm_command = self._get_emssim().cmd_alarm()
        self._assert(alarm_command.run('clear'), "Clearing alarm history failed")

    def _parse_alarms_provided_by_user(self, alarms):
        alarm_list = []
        if isinstance(alarms, six.string_types):
            alarm_list = self._parse_alarm_string(alarms)
        else:
            alarm_list = alarms
        return [str(alarm) for alarm in alarm_list]

    def _parse_alarm_string(self, alarm_string):
        return self._format_comma_or_space_separated_string_given_by_user(alarm_string)
